<?php $host = "localhost"; $user = "root"; $pass = ""; $dbname = "codepixel_studio"; $conn = new mysqli($host, $user, $pass, $dbname); if ($conn->connect_error) { die("Connection failed: " . $conn->connect_error); } $sql = "CREATE DATABASE IF NOT EXISTS codepixel_studio"; if ($conn->query($sql) === TRUE) { echo "Database created successfully<br>"; } mysqli_select_db($conn, $dbname); $messages = "CREATE TABLE IF NOT EXISTS messages ( id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL, service VARCHAR(50) NOT NULL, budget VARCHAR(50), project TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP )"; $reviews = "CREATE TABLE IF NOT EXISTS reviews ( id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, country VARCHAR(50), service VARCHAR(50) NOT NULL, rating INT NOT NULL, review TEXT NOT NULL, permission TINYINT(1) DEFAULT 0, verified TINYINT(1) DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP )"; if ($conn->query($messages) === TRUE) { echo "Messages table created<br>"; } if ($conn->query($reviews) === TRUE) { echo "Reviews table created<br>"; } echo "Setup complete!"; ?>
